with metrics as (select id, customer_id, device, browser, started_at, country, row_number() over (partition by device order by started_at, id) as event_seq, row_number() over (partition by country, customer_id order by started_at desc, id) as row_seq, row_number() over (partition by customer_id order by started_at, id) as seq_no, first_value(browser, true) over (partition by country, browser order by started_at, id rows between unbounded preceding and current row) as first_known_browser, first_value(browser) ignore nulls over (order by started_at, id rows between unbounded preceding and current row) as first_known_browser_2 from sessions) select date_trunc('year', started_at) as year_start, browser, round(sum(event_seq) / nullif(count(case when browser = 'Firefox' then 1 end), 0), 2) as event_seq_per_firefox, count(case when browser = 'Firefox' then 1 end) as firefox_count, count(*) as row_count, count(*) filter (where device = 'desktop') as desktop_rows, count(case when country = 'UK' then 1 end) as uk_count, min(event_seq) as min_event_seq from metrics group by cube (date_trunc('year', started_at), browser);
